```cpp
#include <concepts>
#include <iostream>
#include <string>

template <std::totally_ordered T>          // requirement: T supports < > <= >= == !=.
const T& larger(const T& a, const T& b) {
    return (a < b) ? b : a;
}

struct Point { int x, y; };                // no ordering.

int main() {
    std::cout << larger(3, 7) << '\n';                          // larger<int>: 7.
    std::cout << larger(2.5, 1.5) << '\n';                      // larger<double>: 2.5.
    std::cout << larger(std::string("pear"), std::string("apple")) << '\n';   // pear.
    std::cout << larger<double>(3, 2.5) << '\n';                // explicit T: 3.
    // larger(3, 2.5);            error: T deduced as both int and double.
    // larger(Point{}, Point{});  error: Point doesn't satisfy totally_ordered.
}
```

